var document = new DocumentMarkdownImporter().Import("```csharp\nvar x = 1;\n```");

var code = (CodeBlockContent)document.Blocks[0].Content!;
// code.Language == "csharp"
// code.Code     == "var x = 1;"

// The exporter grows the fence past any backtick run inside the code,
// so a snippet that itself contains ``` still round-trips.
var markdown = new DocumentMarkdownExporter().Export(document);

var block = new DocumentBlock
{
    Type = DocumentBlockType.Code,
    Order = 0,
    Content = new CodeBlockContent
    {
        Language = "json",
        Code = "{ \"id\": 1 }"
    }
};
